def count_perm(nums, used):
    if len(used) == len(nums):
        return 1
    total = 0
    for x in nums:
        if x in used:
            continue
        used.add(x)
        total += count_perm(nums, used)
        used.remove(x)
    return total

print(count_perm([1, 2, 3, 4, 5], set()))
